["runtime/KickoffAdapter"]=[[local Adapter = {}

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LocalPlayer = Players.LocalPlayer

local function findRemote(name)
	local object = ReplicatedStorage:FindFirstChild(name, true)
	return object and object:IsA("RemoteEvent") and object or nil
end

local OwnershipEvent = findRemote("OwnershipEvent")
local ReplicatedSounds = findRemote("ReplicatedSounds")

local function playKickoffBallSound(ball, velocity)
	local kick = ball:FindFirstChild("Kick")
	if kick and kick:IsA("Sound") then
		kick.Volume = math.clamp(velocity.Magnitude * 0.015, 0.1, 10)
		kick.PlaybackSpeed = math.clamp(velocity.Magnitude * 0.00375 + 1.25, 1, 2.1)
		kick:Play()
	end

	if ReplicatedSounds then
		ReplicatedSounds:FireServer(
			"BallHit",
			ball,
			math.clamp(velocity.Magnitude * 0.015, 0.1, 10)
		)
	end
end

function Adapter.Install(tMechanics)
	assert(type(tMechanics) == "table", "T mechanics module did not return a table")

	-- Keep T's ClientReact untouched. It is the exact T BodyVelocity applier.
	-- Replace only the server/network half with Kick Off's ownership protocol.
	function tMechanics.ServerReact(_, hit, position)
		local ball = hit and hit.Ball
		if not ball or ball.Anchored or not ball.CanCollide then
			return false
		end

		local networkOwner = ball:FindFirstChild("NetworkOwner")
		if networkOwner and networkOwner.Value == LocalPlayer then
			playKickoffBallSound(ball, hit.Velocity)
			return true
		end

		if not OwnershipEvent then
			warn("vrftoprs: Kick Off OwnershipEvent was not found")
			return false
		end

		local isTest = workspace:FindFirstChild("Test") ~= nil
		local reactProtection = not isTest and ball:FindFirstChild("ReactProtection") ~= nil
		local duration = hit.Time or 0.3
		local delayValue = hit.Delays
		local spin = hit.Spin
		local spinPayload = spin or {nil, nil, duration}
		local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

		OwnershipEvent:FireServer(
			ball,
			position or ball.Position,
			hit.Velocity,
			hit.MaxForce,
			spinPayload,
			duration,
			nil,
			nil,
			delayValue,
			ball.AssemblyLinearVelocity,
			LocalPlayer:GetNetworkPing(),
			reactProtection,
			isTest,
			false,
			false,
			root and root.Position or Vector3.zero
		)

		return true
	end

	return tMechanics
end

return Adapter
]],
["runtime/TBallPhysics"]=[[local Physics = {}

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local LocalPlayer = Players.LocalPlayer
local Balls = workspace:WaitForChild("Balls")
local connection
local active = false
local created = {}

local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.IgnoreWater = true
rayParams.RespectCanCollide = true

local function mover(ball, name, className)
	local object = ball:FindFirstChild(name)
	if object and not object:IsA(className) then
		return nil
	end
	if not object then
		object = Instance.new(className)
		object.Name = name
		object.Parent = ball
		created[object] = true
	end
	return object
end

local function calculate(ball)
	local properties = PhysicalProperties.new(0.7, 0.1, 0.91, 5, 6)
	local curve = Vector3.zero
	local stopperMultiplier = 0.9
	local angular = ball.AssemblyAngularVelocity
	local velocity = ball.AssemblyLinearVelocity
	local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
	local horizontalSpeed = math.abs(velocity.X) + math.abs(velocity.Z)
	local horizontalAngular = math.abs(angular.X) + math.abs(angular.Z)
	local side = velocity.Magnitude > 0.001
		and CFrame.lookAt(ball.Position, ball.Position + velocity).RightVector
		or Vector3.xAxis
	local vertical = horizontal.Magnitude > 0.001
		and CFrame.lookAt(ball.Position, ball.Position + horizontal).UpVector
		or Vector3.yAxis
	local ground = workspace:Raycast(
		ball.Position + Vector3.new(0, -1, 0),
		Vector3.new(0, -1, 0),
		rayParams
	)
	local nearGround = ground ~= nil and ground.Instance ~= nil

	if horizontalSpeed < 40 then
		return properties, curve, stopperMultiplier, nearGround
	end

	local direction = velocity.Unit
	local spinReference = Vector3.new(direction.Z, 0, -direction.X)
	if angular.Magnitude > 0 and (spinReference - angular.Unit).Magnitude > 1 then
		curve += vertical * (-horizontalAngular * 0.7)
		stopperMultiplier += 0.1
		if curve.Magnitude > 30 or angular.Magnitude > 30 then
			properties = PhysicalProperties.new(0.7, 0.1 + velocity.Magnitude / 500, 0.76, 5, 6)
		end
		if nearGround then curve *= 0.5 end
	else
		curve += vertical * (horizontalAngular * 1.7)
		if curve.Magnitude > 80 or angular.Magnitude > 80 then
			properties = PhysicalProperties.new(0.7, 0.1, 0.76, 5, 6)
		end
		if nearGround then
			curve *= 0.5
			stopperMultiplier += 0.3
		end
	end

	if angular.Magnitude < 20 then
		if horizontalAngular < 10 and horizontalSpeed > 100 then
			local groundCheck = workspace:Raycast(
				ball.Position + Vector3.new(0, -1, 0),
				Vector3.new(0, -6, 0),
				rayParams
			)
			if not (groundCheck and groundCheck.Instance) then
				local noise = math.noise(ball.Position.X / 15, ball.Position.Z / 15, tick() / 4)
				noise *= horizontalSpeed / (5 + angular.Magnitude)
				local strength = math.clamp(noise, -0.6, 0.6) * horizontalSpeed ^ 1.3
				curve = side * math.clamp(strength, -400, 400)
			end
		end
		return properties, curve, stopperMultiplier, nearGround
	end

	if angular.Magnitude < 40 then
		return properties, Vector3.zero, stopperMultiplier, nearGround
	end

	local amount = math.abs(angular.Y / 6) ^ 1.2 * ((velocity.Magnitude / 43) ^ 2 + 1)
	if angular.Y > 0 then amount = -amount end
	curve = (curve + side * (amount / (math.abs(velocity.Y / 175) + 1)) * 1.15) * 1.2
	return properties, curve, stopperMultiplier, nearGround
end

local function update(ball)
	if not active or not ball:IsA("BasePart") then return end
	local curvePower = mover(ball, "CurvePower", "BodyForce")
	local stopper = mover(ball, "Stopper", "BodyAngularVelocity")
	local stopper2 = mover(ball, "Stopper2", "BodyForce")
	local owner = ball:FindFirstChild("NetworkOwner")
	if not curvePower or not stopper or not stopper2 or not owner then return end

	stopper.P = 3
	local velocity = ball.AssemblyLinearVelocity
	local vx = math.clamp(velocity.X, -80, 80)
	local vz = math.clamp(velocity.Z, -80, 80)
	local properties, curve, multiplier, nearGround = calculate(ball)
	curvePower.Force = curve
	stopper2.Force = Vector3.new(-vx, 0, -vz) * multiplier
	ball.CustomPhysicalProperties = properties

	local slowdown = (40 - (math.abs(vx) + math.abs(vz))) / 16
	local speedTorque = (slowdown > 1 and ball.AssemblyAngularVelocity.Magnitude >= 15) and slowdown or 1
	local spinTorque = ball.AssemblyAngularVelocity.Magnitude < 20 and 1.2 or 0.9
	if nearGround then
		spinTorque += 1.75
		curvePower.Force /= 1.75
	end
	local angular = ball.AssemblyAngularVelocity
	stopper.MaxTorque = Vector3.new(math.abs(angular.X), math.abs(angular.Y), math.abs(angular.Z))
		* (spinTorque + speedTorque)

	for _, part in ipairs(ball:GetTouchingParts()) do
		if part.Material == Enum.Material.Grass then
			local bodyVelocity = ball:FindFirstChildOfClass("BodyVelocity")
			if owner.Value == LocalPlayer and bodyVelocity and bodyVelocity.Velocity.Magnitude > 0
				and bodyVelocity.Velocity.Unit.Y < 0 and bodyVelocity.MaxForce.Y ~= 0 then
				bodyVelocity.MaxForce -= Vector3.new(0, bodyVelocity.MaxForce.Y, 0)
			end
			break
		end
	end

	if owner.Value == LocalPlayer and ball.AssemblyLinearVelocity == Vector3.zero then
		ball:ApplyImpulse(Vector3.new(0, -0.1, 0))
	end
end

function Physics.Start()
	if active then return end
	active = true
	connection = VRFConnect(RunService.Stepped, function()
		for _, ball in ipairs(Balls:GetChildren()) do
			if ball.Name == "VRF" then pcall(update, ball) end
		end
	end)
end

function Physics.Stop()
	active = false
	if connection then connection:Disconnect() connection = nil end
	for object in pairs(created) do
		pcall(function() object:Destroy() end)
	end
	table.clear(created)
end

return Physics
]],
["support/ChatSystemMessages"]=[[return function()

	local TextChatService = game:GetService("TextChatService")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local Remotes = ReplicatedStorage:WaitForChild("Remotes")
	local SystemMessageEvent = Remotes:WaitForChild("lllIlllllllIIIlllllIlIIIllllIIIII")

	local TextChannels = TextChatService:WaitForChild("TextChannels")
	local RBXGeneral = TextChannels:WaitForChild("RBXGeneral")

	-- Custom rendering for system messages with encoded color
	TextChatService.OnIncomingMessage = function(message)
		if message.TextSource == nil and message.Metadata then
			local splitMeta = string.split(message.Metadata, ":")
			if splitMeta[1] == "PeriusMessage" and splitMeta[2] then
				local hexColor = splitMeta[2]

				local props = Instance.new("TextChatMessageProperties")
				props.Text = string.format("<font color='%s'>%s</font>", hexColor, message.Text)
				return props
			end
		elseif message.TextSource then
			local playerName = message.TextSource.Name
			message.PrefixText = "[" .. playerName .. "]"
		end
	end

	-- Listen for remote system messages
	VRFConnect(SystemMessageEvent.OnClientEvent, function(data)
		if typeof(data) ~= "table" then return end

		local text = data.Message
		local color = data.Color
		local metadata = data.Metadata

		if typeof(text) == "string" and typeof(color) == "Color3" and metadata == "PeriusMessage" then
			local hexColor = string.format("#%02X%02X%02X", color.R * 255, color.G * 255, color.B * 255)
			local metadataWithColor = metadata .. ":" .. hexColor
			RBXGeneral:DisplaySystemMessage(text, metadataWithColor)
		end
	end)
end

]],
["support/currentplayermodule"]=[=[--[[
	PlayerModule - This module requires and instantiates the camera and control modules,
	and provides getters for developers to access methods on these singletons without
	having to modify Roblox-supplied scripts.

	2018 PlayerScripts Update - AllYourBlox
--]]

local PlayerModule = {}
PlayerModule.__index = PlayerModule

function PlayerModule.new()
	local self = setmetatable({},PlayerModule)
	self.cameras = require(script:WaitForChild("CameraModule"))
	self.controls = require(script:WaitForChild("ControlModule"))
	return self
end

function PlayerModule:GetCameras()
	return self.cameras
end

function PlayerModule:GetControls()
	return self.controls
end

function PlayerModule:GetClickToMoveController()
	return self.controls:GetClickToMoveController()
end

return PlayerModule.new()

]=],
